make('huang_yihe','黄义和教授',B,
'黄义和是研究脑部神经活动的学者，在大学授课，与各地科学家保持通信，日常却显得孤僻而不愿多谈课程之外的事。安妮敬重他的学问，选修他的课程，多次到郊外住所上课，以为他独自生活；实际上他在卧室隔出小房，秘密照护一名遭枪击而长期不能正常行动的政治领袖。这项治疗来自领袖支持者的委托，保密既保护患者，也使教授独自承担巨大风险。黄义和运用新的方法让病人说出重大阴谋，却因受伤大脑无法负荷而导致病人死亡。他写信通知病人的父亲，随后住所起火，本人逃亡；结尾仍以推断说明纵火和毁尸动机，不能把所有细节改写成他当庭承认的事实。他曾在办公室显眼处留下涉及宇宙中心会和卢利根的字条，使安妮找到线索，也因此遭到袭击。警方最后凭信件邮戳找到他，他用新的电震疗法救醒安妮，证明先前治疗事故并不等于完全无能，也不等于从此能无风险修复一切脑伤。他与领袖父亲密谈后共同离去，掌握的政治秘密成为遏制阴谋的条件。角色要保留研究热情、孤僻、防卫性的保密和失败后的逃避，让善后行动与早先责任同时存在。',
'被警方找到，治疗安妮使她恢复清醒，与受害领袖父亲密谈后共同离开。','剧情脑神经治疗研究','以小说中的实验性电震与神经研究尝试恢复受损脑部功能，能够让特定患者短时恢复表达。','需要仪器、病理判断与照护；一例患者因负荷过重死亡，不能任意复活、恢复所有记忆或修复任何脑损。',[(18,20,'课程与研究领域。'),(78,96,'专著、孤僻和学术联系。'),(220,244,'改建房间与纵火推断。'),(774,776,'留下组织线索。'),(1720,1744,'信件、实验事故和搜寻。'),(1876,1904,'安妮获救与离去。')],
'探索脑功能并保护研究与病人，却在政治压力和重大失误前以保密、逃离求生。',[('有复杂脑伤需要治疗','具备仪器和研究条件','提出有边界的实验方案，不能把一次成功当成可靠万能术。'),('自己掌握危及性命的秘密','公开求助也可能招来追杀','隐匿并留下有限记录，可能使旁人承担未知风险。'),('新的患者需要救治','已能判断治疗负荷与可行性','把研究用于挽救眼前的人，承担既有失败的记忆。')],roles=('单书主角','阶段性对立者'),scores=(0,1,1,2,1,1),tier='并',uncertainties=['火灾及毁尸的具体动机在结尾仍由人物推断，未给教授逐项自白。','治疗机制为原作设定，不作现实医学结论。'])
make('luligen','卢利根勋爵',B,
'卢利根是把个人权力隐藏在国家和组织背后的政治操盘者。原文追述他在德国战时主持军火生产，战败后失踪，后来以非洲新国家总统顾问身份重新出现。他帮助若干国家取得政权，住在沙漠中的堡垒，以名画、国宝和替自己奔走的政治人物展示支配力。宇宙中心会的行动并不只依靠杀手，还依靠巨额资金、空壳公司、监控和层级保密；陆嘉与陈思空都是其实际行动的重要人物。他牵涉一位大国领袖遭刺后的秘密，追查知道内情的黄义和，想阻止阴谋被公开。木兰花讲出的事件经过有推测成分，结尾领袖父亲的说明与教授提供的信息才进一步证实核心，卡片不会把她每一句试探都算成勋爵已经承认的历史。他接见木兰花，先看穿部分虚张声势，再用书房玻璃罩将她困住，饶有兴趣地等待她缺氧死亡。他认为金钱、政治与技术足以压倒个人，却在木兰花假死脱困、陈思空心理崩溃后被近身制住。最后他被迫安排飞机，随木兰花离境后穿着降落伞弹出，后续政治活动又受公开秘密的威胁约束。组织没有因此被彻底摧毁，他本人也没有因此变成无所不能的世界支配者。',
'被木兰花挟持离堡，在边界附近穿降落伞弹出；领袖父亲计划以公开阴谋约束其后续干涉。','政治网络与设施控制','通过资金、代理人、层级情报和实际控制的军政设施运作；书房机关可隔离来客并限制空气。','网络需要国家保护与执行者，个人仍是普通血肉；近身失控、部下动摇和关键秘密外泄都能限制他。',[(1164,1180,'身份、军火及政治势力。'),(1326,1334,'组织规模与个人边界。'),(1450,1518,'堡垒和权威展示。'),(1540,1622,'交锋与信息试探。'),(1640,1666,'玻璃罩机关。'),(1828,1866,'被挟持、离堡与弹出。'),(1886,1906,'证据约束及后续计划。')],
'把政治、财富和秘密变成个人支配的工具，对挑战者先衡量利用价值，再考虑消灭。',[('有人自称掌握秘密求见','仍在自己设施与监控范围','以有限接触试探真伪，避免直接承认全部信息。'),('来客突然近身行动','预设机关能够启动','启动隔离手段，以技术和时间消耗取胜。'),('部下失效使本人被控制','身体面临直接致命威胁','被迫让步并安排通行，威望不能替代防护。')],roles=('反派',),scores=(0,1,3,3,2,3),tier='并',appearance='鹰鼻、目光有神，神态坚硬且善于控制表情；外界以年老政治人物认识他，正式见面时叙述又称中年面貌。',uncertainties=['政治领袖未在正文直呼姓名，不能把本书阴谋解释当作现实历史。','木兰花所谓十年不敢干涉是判断，非绝对规则或已观察十年结果。'])
make('chen_sikong','陈思空',B,
'陈思空是年逾八十的内家武术高手，少年时代与霍元甲交手、影响儿岛的经历都通过本书人物追忆呈现，属于小说内部的武学史。他长期隐匿行踪，在宇宙中心会行动时装成平庸老校役，以缓慢步态和衰老外表遮蔽真实能力。他不愿受陆嘉指挥，宣称偷袭时只伤不杀，把武术家的体面与正面较量看得很重，却仍在背后重伤穆秀珍，并压制安妮颈部使她失去正常反应；这套自我评价并不等于公正。他能以拳打折碗口粗的树，近身解除木兰花擒拿，受膝击仍可反击逃离，但面对高翔枪口不得不停步。被拘留后，他配合卢所长以假枪、血迹和主动控制呼吸心跳装死逃出，不是真遭枪杀后复活。他后来守在卢利根身边，因确信木兰花已经窒息，解除玻璃罩时被突然砍断左胫骨。无法理解她实际从地面缝隙换气，他误信她掌握延寿的龟息功，恐惧与求生欲压过原来的自傲，转而配合放走她。终局他用椅脚固定断腿，能一拐一拐行动，仍期待秘传；参战保留这个受伤和误解的最后状态，不把全盛腿法或不存在的长生术自动恢复。',
'左胫骨被木兰花砍断，以椅脚固定后行动；仍在古堡，因误信龟息延寿而协助她离去并等待传授。','高阶近身内家武术','以长期练气、爆发力量、擒拿和身体控制实施近身攻击、抗衡徒手打击，并可有准备地装死。','不能抗子弹，假死需要伪造致命伤；最后断腿明显限制移动，怕老与对武学神话的信任可动摇判断。',[(502,546,'内功、名声与自行其是。'),(660,672,'一拳断树。'),(784,788,'压制安妮。'),(1006,1042,'近战抗击反制及枪口制止。'),(1120,1158,'年龄焦虑与武术挑战。'),(1480,1490,'假死机制。'),(1788,1862,'断腿、龟息误判、固定及转向。')],
'以武术造诣和名家荣誉维持自我价值，最怕时间证明一生苦练仍无法摆脱衰老与死亡。',[('被要求服从普通行动头目','认为对方轻视自己的地位','强调独立与武术规矩，却不因此退出实际伤害。'),('对手用枪和组织手段制住自己','无法近身扭转局面','愤怒指责不合武术荣誉，仍须承认现实威胁。'),('出现自己无法解释的生存技巧','误以为关系到延寿且本人已受挫','放下傲慢求教，愿交换协助。')],roles=('反派','转向合作角色'),scores=(3,1,0,3,0,5),tier='并',destruction='有一拳打折碗口树干、重伤穆秀珍内脏和徒手破椅脚的表现；仍属接触范围。',durability='受木兰花膝击可保持战力，但子弹危险真实，失防时胫骨可被打断；不是金刚不坏。',speed='全盛时近身变化和短距突进快于普通人；终局断腿绑夹板，以跛行和有限站位为准。',energy='练气增强身体控制和接触发力，没有远程气功投射。',mind='长期练气与自制不抵消年龄焦虑、名誉刺激和对延寿的盲目信任。',stamina='长期内功训练支持耐力与呼吸控制；需真实空气，未掌握龟息或无限闭气。',intelligence={'in_combat':'擅长识别脉门、变招和控制伤势程度，仍会因确信胜利而让对手贴近弱处。','knowledge':'熟悉传统武术与练气；对现代枪械、机关和心理欺骗的理解有限。','planning':'能伪装校役、配合假死脱押；不掌握组织所有战略秘密。','adaptation':'若相信对方武学超越自己且能延寿，会迅速改变态度。'},uncertainties=['断腿后没有写明痊愈；不恢复全盛机动。','龟息功只是他信以为真的解释，木兰花最后明确否认自己会。'])
make('lu_jia','陆嘉',B,
'陆嘉是卢利根网络中的重要行动人员，第一次现身时化作意大利餐馆中的中年顾客，重复黄义和的饮食习惯，令木兰花怀疑他就是教授。实际上组织已经买下餐馆，把顾客和工作人员都换成自己人，木兰花的伪装从进入现场起便处于对方监视之中。他以夸张笑声引出烟幕和绑架，动员受训人员迅速转车撤离，却没有预料穆秀珍在混乱中伤了十四名部下。他责问陈思空为何不杀人，反遭老武师拒绝听令，显示同一组织中的地位并不意味着能支配所有成员。木兰花反过来利用他害怕上级的心理，让他几次失态；无线电指令到来后，他又立即改口把绑架与伤害说成误会。后半部他穿军服驾驶飞机，指引并迫使木兰花降落在秘密空军基地，再陪她穿越沙漠去见勋爵。他懂得借国家军力和上级声望施压，也知道尸体本身已不是组织所要的东西，信息判断并不迟钝。终局木兰花从古堡脱出，没有逐一交代陆嘉如何反应或受到处分。卡片保留他的效率、精明、等级恐惧和过早轻敌，不把他没有亲手操控的整个政治体系算成个人本领。',
'陪同木兰花到卢利根堡后退出会见；主谋被挟持后的个人处置未述。','秘密行动指挥与飞行','安排伪装场所、烟幕绑架、换车撤离，驾驶飞机并协调武装护送。','依赖部下、场地与上级授予资源；并非组织最高层，陈思空不接受其个人指挥。',[(276,298,'餐馆伪装和识别。'),(494,520,'撤离、伤员与指挥冲突。'),(554,606,'受上级压力及无线电指令。'),(582,594,'替换餐馆人员。'),(1382,1436,'驾机引导、军服与情报交锋。'),(1456,1512,'古堡引见与退出。')],
'以执行效率和上级认可维护地位，向外展示强大组织，向上又惧怕暴露自己的错误。',[('目标进入预先控制的场所','人员和撤离链已安排','发动协同突袭，迅速转移俘虏。'),('对手点出行动失误并提及上司','缺少独立决策余地','情绪受影响，急于修复自己在层级中的形象。'),('代表上级展示资源','对方依赖其引导','以简短命令和有限信息施压，保持实际秘密。')],roles=('反派',),scores=(1,1,2,2,2,3),tier='并')
make('lu_detention_chief','卢所长',B,
'卢所长负责拘留所，曾有极其良好的警务服务记录，因此陈思空被捕后的严密守卫并没有把他当作外来威胁。普通警员依令阻止别人接近疑犯，却允许自己的长官进入；卢所长正是利用这一层制度信任，将卢利根的名字作为带话理由，诱使陈思空走到铁栅前。他当众拔枪制造击中额头的场面，随后转身离去，留下措手不及的下属和一具看似已死的身体。高翔一度以为他杀害了唯一关键证人，后来陈思空在古堡再现，才证明这是用假枪和生理控制配合的假死脱押。卢所长留下录音，称对方提供的条件好到无法拒绝，同时威胁若不合作就活不过片刻。这是他的解释，既能显示贪利与恐惧并存，也不能据此确定全部威胁细节或免除其选择责任。他的可怕之处不是超常射击，而是熟悉程序、掌握可信职位、知道同僚何时不会设防。警方发动追捕，木兰花判断组织可能将他撤往保护国度，正文没有确认最后抓获或确切藏身地点。角色卡保留脱押共犯和逃亡者的身份，不把尚未实现的引渡或司法结果编成终局。',
'以假枪配合陈思空装死脱押后离去，留下录音；被追捕，最后藏身与抓捕结果未述。','职务信任与脱押协作','利用所长权限绕开针对外人的守卫，配合预先安排的假枪和假死制造死亡现场。','需要可信职务和同伙准备；没有子弹复生或随意欺骗全部调查者的能力。',[(1228,1258,'良好记录、现场操作、录音。'),(1260,1266,'追捕与外逃判断。'),(1480,1490,'后续揭明假死和假枪。')],
'在诱人利益和生命威胁下选择出卖职责，以录音道歉减轻心理负担，却没有阻止实际背叛。',[('秘密组织提供丰厚条件','并声称拒绝会遭杀害','可能利用职权合作，同时把责任解释成不得已。'),('守卫只防范外来人员','自己仍被同僚信任','按平常工作姿态接近目标，使异常行动发生得极突然。'),('行动完成即将曝光','已有撤离安排','快速离场，留下解释而不面对受害同僚。')],roles=('反派',),scores=(1,0,1,1,1,2),tier='纸',uncertainties=['拒绝即会被杀为其录音自述；组织未在原文实际展示这一次威胁的实施。','后续只证实脱押骗局，未确认其逃亡地点或最终判决。'])
make('universe_remote_chief','宇宙中心会的遥控谈判者',B,
'这名未具姓名的组织高层在陆嘉审问木兰花时，通过无线电和房内扬声器干预谈话。他能及时知道双方对答，给陆嘉指示，使原本恼怒的行动头目立即改变口风。他没有以声音催眠任何人，实际优势来自预置监听、等级纪律和掌握部分信息。他承认绑架及餐馆行动，却否认放火烧毁黄义和的住宅，提醒木兰花教授未必就是受害者；后面的调查显示这一否认具有实质信息价值。他声称组织出于不得已而行动，并愿意以任何物质代价补偿穆秀珍的伤势，试图把问题限制在赔偿和不再追问之间。与此同时，他又明确拒绝回答涉及秘密的问题，承认真正的核心内容只有最高层知道，这使他既像上级又仍是分层组织中的一环。他身边可听见陈思空的冷笑，却不能因此把他直接认成后来的卢利根，原文没有给出足够的声音或姓名回指。谈判结束后，他允许木兰花自行离开，整个据点迅速撤空。终局没有个人再现或被捕记录，演绎时应保留通过设施说话、在有限知情下争取停火的角色，不把匿名身份扩展成遍布全球的全知监视者。',
'主持据点谈判后安排撤离，个人真实身份和后续未明。','远程监督与有限谈判','利用既有监听和无线电联系纠正下属行动，以赔偿、信息边界和组织纪律控制冲突。','监听需要预设设备与现场；自承并非掌握全部最高机密，未证与卢利根本人同一。',[(598,606,'无线电指示和监听推断。'),(610,650,'否认纵火、赔偿条件及知情边界。'),(650,654,'撤离据点。')],
'阻止局部行动扩大成公开冲突，在保密框架内用有限让步换取对方退出。',[('下属无法回答关键质问','已有监听和通信连接','及时下令改变口径，再亲自接管谈判。'),('己方伤害已无法否认','仍想维持秘密行动','承认可验证部分并提物质补偿。'),('对手追问核心秘密','所知或权限有限','明确拒答，必要时撤弃据点。')],roles=('反派',),scores=(0,0,1,2,1,2),tier='纸',uncertainties=['没有明确证据将扬声器中的人合并为卢利根或陆嘉；暂按单独职能身份建卡。'])
make('unnamed_assassinated_leader','遭刺的大国领袖',B,
'这位大国领袖在故事中始终没有被直呼姓名，先以火场里无法辨认的身体出现。他生前是一位年轻、有魄力并推动改革的政治人物，政策触动政敌与利益集团，引出借卢利根策划暗杀的阴谋。木兰花依据枪伤、政治关系和异常保密逐步推测他的身份，后来父亲到访与黄教授的信件确认他曾在枪击后存活。公开世界早已接受他死亡的消息，支持者却秘密保存其生命，希望治疗脑部和脊椎伤害，并从他口中获知阴谋的关键。这样，他既是重大政治斗争中的行动者，也是长期失去表达和自理能力的患者，不能把卧床期间写成仍能指挥整个国家。黄义和新的治疗使他短时恢复说话，秘密终于得到传递，但受损大脑因负荷过重而死亡，遗体后来在火灾中被烧毁。叙事借明显的历史联想构成悬疑，角色库仍按本书无名身份记录，不把虚构内幕套作现实人物事实。用于剧情完结后的参战时，可以明示恢复其最后清醒表达形态，保留改革意愿、遇害和被隐匿的经历；这种恢复不授予治愈、政治号令或生前国家全部资源，身体限制也不能靠领袖地位自动消失。',
'遭枪击后秘密存活，实验性治疗中说出阴谋后因脑部负荷过重死亡，遗体后焚毁。','政治判断与秘密证言','生前能推动改革并识别政治交易；最终短时清醒提供关于暗杀的关键事实。','原作最后清醒时已有严重脑部和脊椎损伤，不能恢复生前行动体能；国家权力不随个人自动携带。',[(138,164,'旧枪伤和失能证据。'),(1278,1296,'身份及政治背景推测。'),(1560,1588,'交锋中的政治故事及推测界限。'),(1708,1734,'父亲确认存活、治疗与死亡。'),(1886,1904,'秘密传递后的处理。')],
'生前希望以自己的政策改变国家，最后的清醒表达成为别人理解阴谋与选择善后的依据。',[('面对以庇护换取政治控制的交易','仍可自主作决定','倾向维护自己的判断和公共政策目标，不自动屈从强权。'),('获得短时清醒表达的机会','身体与语言能力允许','优先交代关键人物和事实，不能无限持续演讲或思考。'),('他人把领袖名义当作无限资源','本人没有实际职务与联系','区分政治影响、旧声望和眼下真正可用的手段。')],roles=('单书主角',),scores=(0,0,0,0,0,1),tier='纸',dead=True,durability='最后清醒形态仍有重度枪伤后遗，身体脆弱，不能承担常规格斗。',speed='以最后可表达而非完整行动的病后形态为准，需要外部移动协助。',stamina='脑部负荷曾直接导致死亡；持续表达和决策能力必须严格受限。',uncertainties=['不据历史暗示补出真实姓名、演说、政策细节或原文未述的凶手姓名。'])
make('unnamed_leader_father','遭刺领袖的父亲',B,
'这位乘坐轮椅的老人曾是显赫政治人物，退居幕后后仍有足以支持儿子登上国家领导位置的关系与力量。儿子遇刺，他和支持者选择公开宣布死讯，暗中寻找脑科专家，希望保存生命并查明阴谋。他不是因为已经知道全部内幕才来找木兰花与高翔，恰恰相反，他收到黄义和的信，才获知治疗已有短暂成果而儿子最终死亡，教授所知的关键内容仍是他迫切需要的答案。来访时，他带着受过保安训练的随从，言语简洁有力，把信件交给高翔，提供邮戳线索，促成警方找到教授。他听说木兰花独自去见卢利根，表现出真实关切，承认即便能力很强也可能被那种组织吞没。与黄教授密谈后，老人本可立即揭发政敌，却选择考虑国家秩序：那些人已身居要职，全面公开可能造成严重政治混乱。他计划使涉案者逐个退出政坛，同时以公布证据作为对卢利根的约束。这是已经提出的善后策略，不能写成所有政敌已经被清除。他离开时带走教授，个人伤痛、政治经验和克制同时存在，也不因家族势力便拥有任意操纵国家或让死去儿子复活的能力。',
'得知教授提供的秘密后，与教授共同离开，计划逐步排除政敌并以公开内幕警告卢利根。','政治关系、保密与风险权衡','通过支持者、医疗委托和外交住宿保护调查，以证据和分步政治安排限制阴谋影响。','本人年老需轮椅与随从；资源依赖具体政治关系，计划尚未等同已完成清算。',[(1702,1758,'来访、信件、求证与关切。'),(1882,1906,'密谈、克制与后续计划。')],
'为儿子寻求真相与责任，同时避免私人复仇把国家拖入更大灾难。',[('出现有关儿子命运的新证据','能联系可信调查者','亲自求证并交出有用材料。'),('盟友试图独自接近危险权势者','知道对方组织的强大','明确表示担忧，不把勇敢等同必然安全。'),('公开真相可能引发全国动荡','已掌握足以施压的秘密','选择分步退出与证据威慑，承担暂缓公开的代价。')],roles=('单书主角',),scores=(0,0,1,2,1,2),tier='纸',speed='依赖轮椅和随从移动，未见可用于战斗的快速身法。',uncertainties=['无名角色只按本书身份记录，不补现实历史姓名。','逐个排除政敌与写信威慑是提出的计划，后续执行未展示。'])
